mapper.select:
SELECT METRIC_ID AS "metricId", METRIC_VALUE AS "metricValue"
FROM T_MT_METRIC_VALUE_LATEST
WHERE NODE_ID = #{nodeId}

mapper.insert:
MERGE INTO T_MT_METRIC_VALUE_LATEST t USING ( SELECT NODE_ID, METRIC_ID, SERVER_IP, METRIC_VALUE, SOURCE_TIME FROM ( SELECT q.*, ROW_NUMBER() OVER ( PARTITION BY NODE_ID, METRIC_ID, SERVER_IP ORDER BY SOURCE_TIME DESC) AS RN FROM (
SELECT #{item.nodeId} AS NODE_ID, #{item.metricId} AS METRIC_ID, #{item.serverIp} AS SERVER_IP, #{item.metricValue} AS METRIC_VALUE, NVL(TO_DATE(#{item.sourceTime}, 'YYYY-MM-DD HH24:MI:SS'), SYSDATE) AS SOURCE_TIME FROM DUAL
) q ) r WHERE r.RN = 1 ) s ON (t.NODE_ID = s.NODE_ID AND t.METRIC_ID = s.METRIC_ID AND (t.SERVER_IP = s.SERVER_IP OR (t.SERVER_IP IS NULL AND s.SERVER_IP IS NULL))) WHEN MATCHED THEN UPDATE SET COLLECT_ID = #{collectId}, METRIC_VALUE = s.METRIC_VALUE, SOURCE_TIME = s.SOURCE_TIME, CREATE_TIME = SYSDATE WHEN NOT MATCHED THEN INSERT (ID, COLLECT_ID, NODE_ID, METRIC_ID, SERVER_IP, METRIC_VALUE, SOURCE_TIME, CREATE_TIME) VALUES (SYS_GUID(), #{collectId}, s.NODE_ID, s.METRIC_ID, s.SERVER_IP, s.METRIC_VALUE, s.SOURCE_TIME, SYSDATE)

mapper.select:
SELECT h.METRIC_VALUE AS metricValue, TO_CHAR(h.SOURCE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS sourceTime FROM T_MT_METRIC_VALUE_HISTORY h JOIN T_MT_NODE_METRIC_DEF d ON h.METRIC_ID = d.ID WHERE h.NODE_ID = #{nodeId} AND d.METRIC_NAME = #{metricName}
AND h.SERVER_IP = #{serverIp,jdbcType=VARCHAR}
AND h.SERVER_IP IS NULL
AND h.SOURCE_TIME >= TO_DATE(#{startTime}, 'YYYY-MM-DD HH24:MI:SS') AND h.SOURCE_TIME <= TO_DATE(#{endTime}, 'YYYY-MM-DD HH24:MI:SS') ORDER BY h.SOURCE_TIME ASC

SELECT d.METRIC_NAME AS metricName, h.METRIC_VALUE AS metricValue, TO_CHAR(h.SOURCE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS sourceTime FROM T_MT_METRIC_VALUE_HISTORY h JOIN T_MT_NODE_METRIC_DEF d ON h.METRIC_ID = d.ID WHERE h.NODE_ID = #{nodeId}
AND h.SERVER_IP = #{serverIp,jdbcType=VARCHAR}
AND h.SERVER_IP IS NULL
AND h.SOURCE_TIME >= SYSDATE - #{hours} / 24 ORDER BY d.METRIC_NAME, h.SOURCE_TIME ASC
